                                or (s.get(identifier) if s is not node_conf else None)
                            ]
                            if val is not None
                        ),
                        fallback,
                    )
                )(OLD.sources, OLD.node_config_extra, OLD.k, OLD.identifier, OLD.fallback)
                == result
            )
        )
    )
)

